        body: JSON.stringify({ destinationProjectId: destination.value })
      });
      if (!update.ok) {
        showError('Unable to move task');
        return;
      }
      error.hidden = true;
      await loadTasks();
    });
    row.append(title, label, priority, renameForm, dueDateForm, moveForm);
    taskContainer.append(row);
  }
}

